sampleQueries.query:
let actors = ThreatIntelObjects | where SourceSystem == 'Cognyte Luminar' and StixType == 'threat-actor' | extend ActorId = tostring(Data.id), Actor = tostring(Data.name);
let rels = ThreatIntelObjects | where SourceSystem == 'Cognyte Luminar' and StixType == 'relationship' | extend Src = tostring(Data.source_ref), Tgt = tostring(Data.target_ref), Rel = tostring(Data.relationship_type);
let idents = ThreatIntelObjects | where SourceSystem == 'Cognyte Luminar' and StixType == 'identity' | extend IdentityId = tostring(Data.id), Target = tostring(Data.name);
actors | join kind=inner rels on $left.ActorId == $right.Src | join kind=inner idents on $left.Tgt == $right.IdentityId | project Actor, Rel, Target
